INSERT INTO `inventory` VALUES (810,'tf-6168-b-001-55',13,'TF 6168-B 001 55','F04174',NULL,'Introducing the Tom Ford Frame TF5818-B ECO 001 Square Black Eyeglasses Frame, designed for both men and women. This stylish optical frame is lightweight and comfortable, making it ideal for daily wear. Perfect as a prescription glasses frame, it combines modern elegance with practicality, elevating your eyewear game while ensuring clear vision and effortless style.','Our commitment to authenticity ensures that every eyewear product in our collection is sourced directly from Manufacturers or Authorized affiliates.\r\nWe prioritize authenticity, offering only licensed and certified eyewear products.\r\nEnjoy One year Warranty on all Products you Purchase from Us. We stand behind the quality and durability of our products, ensuring they meet your expectations. If you encounter any manufacturing defects or issues within the first year of purchase, our warranty has got you covered. Simply Contact Us and we\'ll swiftly address your concerns, providing you with a hassle-free solution. Choose our eyewear brand for both style and reliability.','eyeglasses',NULL,NULL,NULL,NULL,'55',NULL,39750.00,39750.00,'INR','/storage/products/3IgIANj0qkFbZSH12mnWKFu4JvI2wBEknGjn2dky.jpg','[\"/storage/products/gallery/86eXOnTnkuRUdNa5ZcCEt4nIQLJMAcIu5KNReXdo.jpg\", \"/storage/products/gallery/uB0clky4wyUOnW5jYyZJyrB3BfluUTf3p7eHz3Ia.jpg\"]',1,1,0,0,'2026-08-15 08:59:31','2026-08-15 08:59:31','2026-08-15 09:32:43'),(811,'tf-5634-b-001-53',13,'TF 5634-B 001 53','F04082',NULL,NULL,NULL,'eyeglasses','MALE','SQUARE','PLASTIC','BLACK','53',NULL,36950.00,36950.00,'INR',NULL,NULL,1,1,0,0,'2026-08-15 08:59:31','2026-08-15 08:59:31','2026-08-15 08:59:31'),(812,'tf-6084-b-056-56',13,'TF 6084-B 056 56','F04084',NULL,NULL,NULL,'eyeglasses','MALE','RECTANGLE','PLASTIC','TORTOISE','56',NULL,45950.00,45950.00,'INR',NULL,NULL,1,1,0,0,'2026-08-15 08:59:31','2026-08-15 08:59:31','2026-08-15 08:59:31'),(813,'tf-6035-b-